## 1️⃣ SQL Abstract Syntax Tree (AST) Parser  

### Goal  
*Parse a **limited but useful** subset of ANSI‑SQL (SELECT‑FROM‑WHERE with inner joins) into an immutable AST.*  

### Core Interfaces  

```csharp
// ITokenizer.cs
public interface ITokenizer
{
    IEnumerable<Token> Tokenize(string sql);
}

// IParser.cs
public interface IParser
{
    SelectNode Parse(string sql);
}
```

### Token definition  

```csharp
public enum TokenKind
{
    Identifier,
    StringLiteral,
    Number,
    Symbol,          // e.g. ',', '(', ')', '*'
    Keyword,         // SELECT, FROM, WHERE, JOIN, ON, ...
    EndOfInput
}

public sealed record Token(TokenKind Kind, string Text, int Position);
```

### Simple hand‑rolled tokenizer (good enough for the demo)  

```csharp
public sealed class SqlTokenizer : ITokenizer
{
    private static readonly HashSet<string> Keywords = new()
    {
        "SELECT","FROM","WHERE","JOIN","ON","INNER","LEFT","RIGHT","FULL","AS"
    };

    public IEnumerable<Token> Tokenize(string sql)
    {
        int i = 0;
        while (i < sql.Length)
        {
            // skip whitespace
            if (char.IsWhiteSpace(sql[i])) { i++; continue; }

            // identifiers / keywords
            if (char.IsLetter(sql[i]) || sql[i] == '_')
            {
                int start = i;
                while (i < sql.Length && (char.IsLetterOrDigit(sql[i]) || sql[i] == '_' ))
                    i++;
                var text = sql[start..i].ToUpperInvariant();
                var kind = Keywords.Contains(text) ? TokenKind.Keyword : TokenKind.Identifier;
                yield return new Token(kind, text, start);
                continue;
            }

            // numeric literal
            if (char.IsDigit(sql[i]))
            {
                int start = i;
                while (i < sql.Length && char.IsDigit(sql[i])) i++;
                yield return new Token(TokenKind.Number, sql[start..i], start);
                continue;
            }

            // string literal (single quotes)
            if (sql[i] == '\'')
            {
                int start = i++;
                while (i < sql.Length && sql[i] != '\'') i++;
                if (i >= sql.Length) throw new Exception("Unterminated string literal");
                i++; // consume closing quote
                var text = sql[(start + 1)..(i - 1)];
                yield return new Token(TokenKind.StringLiteral, text, start);
                continue;
            }

            // symbols
            var sym = sql[i].ToString();
            i++;
            yield return new Token(TokenKind.Symbol, sym, i - 1);
        }

        yield return new Token(TokenKind.EndOfInput, string.Empty, i);
    }
}
```

### AST node hierarchy  

All nodes are **immutable** and derive from `SqlNode`. Only the nodes required for the optimizer are shown; you can extend them later.

```csharp
public abstract record SqlNode;

public sealed record SelectNode(
    IReadOnlyList<string> Projections,      // e.g. ["t1.id", "t2.name"]
    FromNode From,
    PredicateNode? Where) : SqlNode;

public sealed record FromNode(
    IReadOnlyList<TableReferenceNode> Tables,
    IReadOnlyList<JoinNode> Joins) : SqlNode;

public sealed record TableReferenceNode(
    string TableName,
    string? Alias) : SqlNode;

public sealed record JoinNode(
    TableReferenceNode Right,
    PredicateNode On,
    JoinType Type = JoinType.Inner) : SqlNode;

public sealed record PredicateNode(
    string Left,      // could be "t1.id"
    string Operator, // '=', '<', etc.
    string Right)    // could be "t2.id" or a constant
    : SqlNode;

public enum JoinType { Inner, Left, Right, Full }
```

### Recursive‑descent parser (still small, but production‑ready enough for demos)  

```csharp
public sealed class SqlParser : IParser
{
    private readonly IEnumerator<Token> _tokens;
    private Token _lookahead = null!;

    public SqlParser(ITokenizer tokenizer)
    {
        // the parser is constructed once per query
        _tokens = tokenizer.Tokenize("").GetEnumerator(); // placeholder
    }

    private void Init(string sql, ITokenizer tokenizer)
    {
        _tokens.Dispose();
        var enumer = tokenizer.Tokenize(sql).GetEnumerator();
        _tokens = enumer;
        MoveNext(); // prime _lookahead
    }

    private void MoveNext()
    {
        if (_tokens.MoveNext())
            _lookahead = _tokens.Current;
        else
            _lookahead = new Token(TokenKind.EndOfInput, string.Empty, -1);
    }

    private void Expect(TokenKind kind, string? value = null)
    {
        if (_lookahead.Kind != kind ||
            (value != null && !string.Equals(_lookahead.Text, value, StringComparison.OrdinalIgnoreCase)))
            throw new Exception($"Expected {kind} {(value ?? "")} but got {_lookahead.Kind} '{_lookahead.Text}'");
        MoveNext();
    }

    // -----------------------------------------------------------------
    // Public entry point
    // -----------------------------------------------------------------
    public SelectNode Parse(string sql)
    {
        Init(sql, new SqlTokenizer());
        return ParseSelect();
    }

    // -----------------------------------------------------------------
    // Grammar helpers (very small subset)
    // -----------------------------------------------------------------
    private SelectNode ParseSelect()
    {
        Expect(TokenKind.Keyword, "SELECT");
        var proj = ParseProjectionList();

        Expect(TokenKind.Keyword, "FROM");
        var from = ParseFrom();

        PredicateNode? where = null;
        if (_lookahead.Kind == TokenKind.Keyword && _lookahead.Text == "WHERE")
        {
            MoveNext(); // consume WHERE
            where = ParsePredicate();
        }

        Expect(TokenKind.EndOfInput);
        return new SelectNode(proj, from, where);
    }

    private List<string> ParseProjectionList()
    {
        var list = new List<string>();
        do
        {
            if (_lookahead.Kind != TokenKind.Identifier && _lookahead.Kind != TokenKind.Symbol && _lookahead.Text != "*")
                throw new Exception($"Unexpected token in projection list: {_lookahead.Text}");
            list.Add(_lookahead.Text);
            MoveNext();

            if (_lookahead.Kind == TokenKind.Symbol && _lookahead.Text == ",")
                MoveNext(); // consume comma
            else
                break;
        } while (true);

        return list;
    }

    private FromNode ParseFrom()
    {
        var tables = new List<TableReferenceNode>();
        var joins = new List<JoinNode>();

        tables.Add(ParseTableReference());

        while (_lookahead.Kind == TokenKind.Keyword && _lookahead.Text == "JOIN")
        {
            MoveNext(); // consume JOIN
            var right = ParseTableReference();
            Expect(TokenKind.Keyword, "ON");
            var pred = ParsePredicate();
            joins.Add(new JoinNode(right, pred, JoinType.Inner));
        }

        return new FromNode(tables, joins);
    }

    private TableReferenceNode ParseTableReference()
    {
        if (_lookahead.Kind != TokenKind.Identifier)
            throw new Exception($"Expected table name, got {_lookahead.Text}");
        var name = _lookahead.Text;
        MoveNext();

        string? alias = null;
        if (_lookahead.Kind == TokenKind.Keyword && _lookahead.Text == "AS")
        {
            MoveNext(); // consume AS
            if (_lookahead.Kind != TokenKind.Identifier)
                throw new Exception("Expected alias after AS");
            alias = _lookahead.Text;
            MoveNext();
        }
        else if (_lookahead.Kind == TokenKind.Identifier) // implicit alias
        {
            alias = _lookahead.Text;
            MoveNext();
        }

        return new TableReferenceNode(name, alias);
    }

    private PredicateNode ParsePredicate()
    {
        // Very simple: <identifier> <op> <identifier|literal>
        if (_lookahead.Kind != TokenKind.Identifier)
            throw new Exception($"Expected left side of predicate, got {_lookahead.Text}");
        var left = _lookahead.Text;
        MoveNext();

        if (_lookahead.Kind != TokenKind.Symbol && _lookahead.Kind != TokenKind.Keyword)
            throw new Exception($"Expected operator, got {_lookahead.Text}");
        var op = _lookahead.Text;
        MoveNext();

        if (_lookahead.Kind != TokenKind.Identifier &&
            _lookahead.Kind != TokenKind.Number &&
            _lookahead.Kind != TokenKind.StringLiteral)
            throw new Exception($"Expected right side of predicate, got {_lookahead.Text}");
        var right = _lookahead.Text;
        MoveNext();

        return new PredicateNode(left, op, right);
    }
}
```

> **Why a hand‑rolled parser?**  
> * It keeps the demo self‑contained (no external ANTLR dependency).  
> * You can replace it later with a full‑featured parser without touching the optimizer core – just implement `IParser`.  

